import{z as s,x as l,o as B,c as d,q as A,j as n,D as e,d as E,s as o,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"投资者行为损耗","description":"","frontmatter":{"title":"投资者行为损耗","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-investor-behavior-drag.md","filePath":"quant/ap-investor-behavior-drag.md","lastUpdated":1791413859000}'),p={name:"quant/ap-investor-behavior-drag.md"};function h(m,a,D,R,c,u){const t=l("Mermaid");return B(),d("div",null,[a[2]||(a[2]=A('<h1 id="投资者行为损耗" tabindex="-1">投资者行为损耗 <a class="header-anchor" href="#投资者行为损耗" aria-label="Permalink to &quot;投资者行为损耗&quot;">​</a></h1><div class="epigraph"><p>投资者实际到手的美元加权回报，系统性地低于同期资产的时间加权回报：钱在高位进来，在低位出去。</p><footer>—— Dichev, What Are Stock Investors&#39; Actual Historical Returns? Evidence from Dollar-Weighted Returns, American Economic Review, 2007</footer></div><p><a href="/quant/ap-performance-persistence">上一课</a>说明产品层的净超额持续性弱，且难测。评估的最后一层损耗不在产品里，而在持有人自己：同一只基金，时间加权收益与投资者实际拿到的美元加权收益之间，隔着一条方向稳定的缺口。本课把第一课并排报的两个口径，变成一张对账表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一课说 TWR 剔除现金流时点、MWR 保留它，那是口径之争；现在是事实之争：\\(R_{\\mathrm{MWR}}-R_{\\mathrm{TWR}}\\) 的差有多大、朝哪边偏。机制不复杂：申赎追逐近期业绩（见<a href="/quant/fund-flows-chasing">基金流与回报追逐</a>），资金恰好在业绩高点在场、低点缺席——问题常常不是买了差的基金，而是好基金也被坏时点吃掉。Barber 与 Odean 对数万个个人账户的实证给出同向证据：交易越频繁，净收益越低，过度交易自己就把回报磨掉了。缺口是把它从 anecdote 变成可复算的年化数：缺口多大、拆成哪几项、什么规则能收窄它。</p><p><span class="marginnote">术语翻译：TWR（时间加权收益）衡量「基金本身赚多少」，申赎动作被剔除；MWR（美元加权收益）衡量「你的钱实际赚多少」，进出时点被完整计入。两者之差不是记账误差，而是行为损耗——钱高进低出，损耗就归你。</span></p><h3 id="缺口的分解" tabindex="-1">缺口的分解 <a class="header-anchor" href="#缺口的分解" aria-label="Permalink to &quot;缺口的分解&quot;">​</a></h3><p>行为损耗约等于两项之和：<strong>时点项</strong>——资金在场时的加权收益与全程收益之差；<strong>成本项</strong>——每次追涨杀跌付出的申赎费与市场摩擦。度量方法：同一基金池并行算 TWR 序列与按流量加权的 MWR，年化差就是缺口；实务口径如 Morningstar 的 Mind the Gap 系列，多年把缺口稳定测在每年 1.5 个百分点上下，且随市场周期放大缩小。</p><p><span class="marginnote">一笔干净的算术：基金第一年涨 50%、第二年跌 20%，TWR 为 \\(1.5\\times 0.8-1=+20\\%\\)；持有人在第一年末的高点才申购，其 MWR 是 \\(-20\\%\\)。同一基金、同两年，两个口径差 40 个百分点——基金没骗人，时点把钱让了出去。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>做账户对账表：每个账户同报两条曲线——单位净值的 TWR 与账户市值加现金流的 IRR，差额年度化、按账户分层。归因：把缺口拆成时点项（各子区间在场权重乘该段收益，对比平均权重）与成本项（申赎费加摩擦，直接从第二课的费用瀑布读数）。干预评估：把规则化方案——定投、缴款自动化、<a href="/quant/rebalance-rules">再平衡规则</a>、赎回冷静期——放进历史流量里重放，比较干预前后的 MWR 分布，而不是靠教育口号。</p>',11)),(B(),n(i,null,{default:e(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PERF%5B%22%E5%9F%BA%E9%87%91%20TWR%20%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20GAP%7B%22MWR%20-%20TWR%22%7D%0A%20%20FLOW%5B%22%E7%94%B3%E8%B5%8E%E6%B5%81%E9%87%8F%22%5D%20--%3E%20TIMING%5B%22%E6%97%B6%E7%82%B9%E9%A1%B9%3A%20%E5%9C%A8%E5%9C%BA%E6%9D%83%E9%87%8D%E5%81%8F%E7%A6%BB%22%5D%0A%20%20BEHAV%5B%22%E8%BF%BD%E9%80%90%E4%B8%8E%E5%A4%84%E7%BD%AE%E6%95%88%E5%BA%94%22%5D%20--%3E%20FLOW%0A%20%20FLOW%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E9%A1%B9%3A%20%E7%94%B3%E8%B5%8E%E8%B4%B9%E4%B8%8E%E6%91%A9%E6%93%A6%22%5D%0A%20%20TIMING%20--%3E%20GAP%0A%20%20COST%20--%3E%20GAP%0A%20%20GAP%20--%3E%20RULE%5B%22%E8%A7%84%E5%88%99%E5%8C%96%E5%B9%B2%E9%A2%84%3A%20%E5%AE%9A%E6%8A%95%2F%E5%86%8D%E5%B9%B3%E8%A1%A1%2F%E8%87%AA%E5%8A%A8%E5%8C%96%22%5D%0A%20%20RULE%20--%3E%20REPLAY%5B%22%E6%B5%81%E9%87%8F%E9%87%8D%E6%94%BE%3A%20%E7%BC%BA%E5%8F%A3%E6%94%B6%E7%AA%84%E4%BA%86%E5%90%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[E("缺口方向为什么稳定：流量对过去收益的弹性为正、对未来收益的弹性为负——追逐者系统性在均值回复点入场；处置效应（卖盈保亏）与可得性（近期新闻放大感知风险）把申赎时点推向分布两端。这不是教育能完全修复的：基金评价体系按 TWR 排名发星级，投资人看到的数与他拿到手的数本来就不是同一个；评价机制自己在校准错误的目标。机制修复是把时点判断从人移交给规则——定投消解入场时点，再平衡把「高抛低吸」变成无条件执行，税收损失收割同理（"),r("a",{href:"/quant/tax-aware-portfolio"},"税务感知组合"),E("）。规则不更聪明，规则只是不恐惧也不贪婪。")],-1)),(B(),n(i,null,{default:e(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOT%5B%22%E5%9F%BA%E9%87%91%E8%BF%91%E6%9C%9F%E4%B8%9A%E7%BB%A9%E4%BA%AE%E7%9C%BC%22%5D%20--%3E%20CHASE%5B%22%E8%B5%84%E9%87%91%E8%BF%BD%E8%BF%9B%E6%9D%A5%3A%20%E6%B5%81%E9%87%8F%E8%B7%9F%E7%9D%80%E8%BF%87%E5%8E%BB%E6%94%B6%E7%9B%8A%E8%B5%B0%22%5D%0A%20%20CHASE%20--%3E%20LATE%5B%22%E5%85%A5%E5%9C%BA%E7%82%B9%E5%B8%B8%E8%90%BD%E5%9C%A8%E4%B8%8A%E6%B6%A8%E6%AE%B5%E6%9C%AB%E7%AB%AF%22%5D%0A%20%20MR%5B%22%E9%9A%8F%E5%90%8E%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%E6%88%96%E5%9B%9E%E6%92%A4%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20PANIC%5B%22%E6%81%90%E6%85%8C%E8%B5%8E%E5%9B%9E%3A%20%E6%B5%81%E9%87%8F%E5%8F%88%E5%8F%8D%E5%90%91%E8%B5%B0%22%5D%0A%20%20DISP%5B%22%E5%A4%84%E7%BD%AE%E6%95%88%E5%BA%94%3A%20%E5%8D%96%E7%9B%88%E4%BF%9D%E4%BA%8F%22%5D%20--%3E%20PANIC%0A%20%20LATE%20--%3E%20RES%5B%22%E9%AB%98%E7%82%B9%E5%A4%9A%E5%9C%A8%E5%9C%BA%2C%20%E4%BD%8E%E4%BD%8D%E5%B8%B8%E7%BC%BA%E5%B8%AD%22%5D%0A%20%20PANIC%20--%3E%20RES%0A%20%20RES%20--%3E%20NEG%5B%22MWR%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E4%BD%8E%E4%BA%8E%20TWR%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">直觉类比：TWR 像一家餐厅全年的平均水平，MWR 像你专挑它上新闻最火的周末去排队的体验。餐厅没变差，是你的到场时点集中在了最拥挤的时候——追逐热度本身就把体验变糟了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>行为损耗是账户层现象，不能拿来给基金评级翻案：考核管理人只看净 TWR（口径按第一课钉死），考核顾问与平台看 MWR 对账。缺口估计对流量数据质量敏感：外部转入转出与收益混淆会伪造时点项。个人账户的过度交易证据以 Barber–Odean 的美国样本为准，制度环境不同（申赎成本、税费、赎回时滞）幅度会移，方向机制不变。最后一课把八课合回一张图，评价到此可以闭环。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(R_{\\mathrm{MWR}}-R_{\\mathrm{TWR}}\\) 是可复算的对账缺口，方向系统性为负。</li><li>缺口两项：时点项（在场权重偏离）加成本项（申赎费与摩擦）。</li><li>机制：追逐近期业绩与处置效应把时点推向分布两端，规则化干预可收窄。</li><li>考核分工：管理人看净 TWR，顾问与平台看 MWR 对账，不可互相顶替。</li><li>出处：Dichev, <em>American Economic Review</em>, 2007；Barber and Odean, <em>Journal of Finance</em>, 2000；缺口幅度据 Morningstar, Mind the Gap 系列报告整理。</li></ul>',5))])}const C=s(p,[["render",h]]);export{f as __pageData,C as default};
